                        jmethodID toArrayMid = env->GetMethodID(collCls, "toArray", "()[Ljava/lang/Object;");
                        jobjectArray arr = (jobjectArray)env->CallObjectMethod(values, toArrayMid);
                        env->DeleteLocalRef(collCls);
                        env->DeleteLocalRef(values);
